package kindergarten

import (
	"fmt"
	"sort"
	"strings"
)

var plants = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

type Garden struct {
	diagram  []string
	children []string
}

func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, fmt.Errorf("diagram must start with a newline")
	}
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, fmt.Errorf("diagram must have two rows")
	}
	for _, row := range rows {
		if len(row)%2 != 0 {
			return nil, fmt.Errorf("rows must have an even number of cups")
		}
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, fmt.Errorf("rows must be the same length")
	}
	for _, r := range rows[0] + rows[1] {
		if _, ok := plants[r]; !ok {
			return nil, fmt.Errorf("invalid plant code %q", r)
		}
	}
	// check duplicates
	seen := make(map[string]bool)
	for _, c := range children {
		if seen[c] {
			return nil, fmt.Errorf("duplicate child %q", c)
		}
		seen[c] = true
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	return &Garden{diagram: rows, children: sorted}, nil
}

func (g *Garden) Plants(child string) ([]string, bool) {
	idx := sort.SearchStrings(g.children, child)
	if idx >= len(g.children) || g.children[idx] != child {
		return nil, false
	}
	res := make([]string, 0, 4)
	for _, row := range g.diagram {
		res = append(res, plants[row[2*idx]], plants[row[2*idx+1]])
	}
	return res, true
}
```

