package kindergarten

import (
	"fmt"
	"sort"
	"strings"
)

// Garden holds a diagram of two rows of cups and the list of children,
// sorted alphabetically, each assigned two cups per row in order.
type Garden struct {
	rows     []string // exactly two rows of cup codes
	children []string // sorted alphabetically
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses the diagram and the list of children.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
//
// NewGarden returns an error if the diagram is malformed (missing leading
// newline, not exactly two rows, mismatched row lengths, odd number of
// cups, or invalid cup codes) or if the children list contains duplicates.
// The children argument is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, fmt.Errorf("diagram must start with a newline")
	}
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, fmt.Errorf("diagram must have exactly two rows, got %d", len(rows))
	}
	for i, row := range rows {
		if len(row)%2 != 0 {
			return nil, fmt.Errorf("row %d has an odd number of cups: %d", i+1, len(row))
		}
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, fmt.Errorf("mismatched row lengths: %d and %d", len(rows[0]), len(rows[1]))
	}
	for _, row := range rows {
		for _, r := range row {
			if _, ok := plantNames[r]; !ok {
				return nil, fmt.Errorf("invalid cup code %q", r)
			}
		}
	}
	seen := make(map[string]bool, len(children))
	for _, c := range children {
		if seen[c] {
			return nil, fmt.Errorf("duplicate child %q", c)
		}
		seen[c] = true
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	return &Garden{rows: rows, children: sorted}, nil
}

// Plants returns the four plants belonging to the named child: the two
// cups of the first row followed by the two cups of the second row.
// The boolean result is false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	idx := sort.SearchStrings(g.children, child)
	if idx >= len(g.children) || g.children[idx] != child {
		return nil, false
	}
	if 2*idx+1 >= len(g.rows[0]) {
		return nil, false
	}
	plants := make([]string, 0, 4)
	for _, row := range g.rows {
		plants = append(plants, plantNames[row[2*idx]], plantNames[row[2*idx+1]])
	}
	return plants, true
}

